import traceback
import textwrap

INDENT = " " * 2

class Group(object):

    """
    A group with members, on which group operations can be executed.
    """

    def __init__(self, members=None, **kwargs):
        """
        Create a group of members.

        :param list members: List of members
        """
        super(Group, self).__init__(**kwargs)
        if members is None:
            members = []
        self._members = members

    @property
    def members(self):
        """
        Member of the group.

        :return: members
        :rtype: list
        """
        return self._members


class GroupError(Exception):
    """
    Exceptions of members of a Group.
    """

    def __init__(self, errors, message="group error"):
        self.errors = errors
        self.message = message

    def __str__(self):
        def _format(errors, level=0):
            lines = []
            for key, exc in errors.items():
                lines.append(INDENT * level + f"{key!r}")
                tb = ''.join(traceback.format_exception(type(exc), exc, exc.__traceback__)).rstrip()
                lines.append(textwrap.indent(tb, INDENT * (level + 1)))
            return '\n'.join(lines)
        return f"{self.message}\n" + _format(self.errors, 1)

    def __repr__(self):
        return (f"{self.__class__.__name__}(message={self.message!r}, errors={{" +
                ", ".join(f"{key!r}: {value!r}" for key, value in self.errors.items()) + "})")

